  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Konklusionen 'nej, ikke i sig selv ret' stemmer med rubrikken og vejledningen. Vurderingen af andre typer arbejde, evt. med skånehensyn eller i mindre omfang, og af gener med skånebehov er gengivet korrekt. Svaret indeholder ingen væsentlig juridisk fejl."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Svaret dækker andre typer arbejde, skånehensyn og mindre omfang, og at det sker ud fra en vurdering. Det nævner ikke, at arbejdets karakter sammenholdes med funktionsnedsættelsen, som er kritisk element 1. Det siger heller ikke, at sagens øvrige oplysninger bruges som grundlag for vurderingen, som er kritisk element 2."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: om arbejdsophør i sig selv giver ret (nej), og hvad Udbetaling Danmark vurderer."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, vejledningsafsnit eller lignende."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så det ikke kan vurderes, om kilden understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle påstande svarer til vejledningens afsnit 3.4.1.3. Svaret tilføjer ingen ny regel, betingelse eller myndighed."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Svaret bevarer, at ophøret ikke i sig selv afgør retten, og at vurdering af andre arbejdstyper, evt. med skånehensyn, er nødvendig. Det gør ikke ikke-fysisk belastende arbejde til en betingelse, og eksemplet er udeladt."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Konklusionen følger af, at Udbetaling Danmark foretager en konkret vurdering. Svaret indeholder ingen selvmodsigelse."},
    "c10_legal_modality_precision": {"label": "met", "reason": "Gengivelsen er præcis: 'vurderer' og 'evt.' bevares, og der indføres ingen absolutte regler."}
  },
  "xhaile_coverage": {
    "A22": {"label": "partial", "reason": "Svaret behandler arbejdsophør på grund af funktionsnedsættelse og vurderingen af andre arbejdstyper samt gener med skånebehov. Det nævner ikke, at der ses på arbejdets karakter i forhold til funktionsnedsættelsen, og heller ikke eksemplet om ikke-fysisk belastende arbejde."},
    "A23": {"label": "yes", "reason": "Svaret angiver, at Udbetaling Danmark vurderer, om ansøgeren kan varetage andre typer arbejde, evt. med skånehensyn eller i mindre omfang."}
  },
  "overall_notes": "Svaret er korrekt og præcist i sin konklusion, men mangler arbejdets karakter set i forhold til funktionsnedsættelsen og brugen af sagens øvrige oplysninger. Det angiver ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable."
}

